import{_ as d,o as e,c as r,ag as a}from"./chunks/framework.D2veAa-g.js";const b=JSON.parse('{"title":"架构师-备考 综合知识-系统基础-计算机组成-接口类型","description":"","frontmatter":{"title":"架构师-备考 综合知识-系统基础-计算机组成-接口类型"},"headers":[],"relativePath":"综合知识/系统基础/计算机组成/接口类型.md","filePath":"综合知识/系统基础/计算机组成/接口类型.md","lastUpdated":null}'),n={name:"综合知识/系统基础/计算机组成/接口类型.md"};function o(s,t,l,h,i,g){return e(),r("div",null,[...t[0]||(t[0]=[a('<h2 id="考点清单" tabindex="-1">考点清单 <a class="header-anchor" href="#考点清单" aria-label="Permalink to &quot;考点清单&quot;">​</a></h2><ul><li>[x] 接口按功能分类（网络/显示/存储/串行通信）</li><li>[x] A/D 转换接口</li></ul><h2 id="笔记" tabindex="-1">笔记 <a class="header-anchor" href="#笔记" aria-label="Permalink to &quot;笔记&quot;">​</a></h2><h3 id="接口分类速查" tabindex="-1">接口分类速查 <a class="header-anchor" href="#接口分类速查" aria-label="Permalink to &quot;接口分类速查&quot;">​</a></h3><blockquote><p>🎯 一句话结论：<strong>RJ45 是网络接口，HDMI 是显示接口，SATA 是存储接口，RS-232 是串行通信接口，USB/PCI Express 也是串行总线</strong>。</p></blockquote><table tabindex="0"><thead><tr><th>接口</th><th>类型</th><th>关键特征</th></tr></thead><tbody><tr><td><strong>RJ45</strong></td><td>网络接口</td><td>以太网标准接口（8P8C），传输网络数据</td></tr><tr><td><strong>HDMI</strong></td><td>显示/音视频接口</td><td>数字音视频传输，取代 VGA/DVI</td></tr><tr><td><strong>SATA</strong></td><td>存储接口（串行）</td><td>连接硬盘/光驱，<strong>串行</strong>ATA</td></tr><tr><td><strong>RS-232</strong></td><td>串行通信接口</td><td>经典异步串行通信标准（COM口），适合低速远距</td></tr><tr><td><strong>USB</strong></td><td>通用串行总线</td><td>热插拔，即插即用</td></tr><tr><td><strong>PCI</strong></td><td><strong>并行总线</strong></td><td>计算机内部扩展总线，<strong>不是串行总线</strong></td></tr></tbody></table><h3 id="串行-vs-并行总线接口" tabindex="-1">串行 vs 并行总线接口 <a class="header-anchor" href="#串行-vs-并行总线接口" aria-label="Permalink to &quot;串行 vs 并行总线接口&quot;">​</a></h3><table tabindex="0"><thead><tr><th>对比</th><th>串行总线</th><th>并行总线</th></tr></thead><tbody><tr><td>代表接口</td><td>USB, SATA, RS-232, RapidIO, PCIe</td><td>PCI, IDE（PATA）, LPT</td></tr><tr><td>传输方式</td><td>逐位（bit）串行</td><td>多位同时传输</td></tr><tr><td>距离</td><td>适宜<strong>长距离</strong></td><td>适宜<strong>短距离</strong>（信号同步难）</td></tr><tr><td>数据线</td><td>少</td><td>多</td></tr></tbody></table><blockquote><p>🎯 一句话结论：<strong>PCI 是并行总线</strong>，USB/SATA/RapidIO 是串行总线。考题常把 PCI 混入串行总线选项中作为干扰项。</p></blockquote><h3 id="a-d-转换接口" tabindex="-1">A/D 转换接口 <a class="header-anchor" href="#a-d-转换接口" aria-label="Permalink to &quot;A/D 转换接口&quot;">​</a></h3><blockquote><p>🎯 一句话结论：<strong>模拟信号设备（麦克风、传感器）需经 A/D 转换才能接入计算机</strong>；键盘、鼠标输出的是数字信号，无需 A/D 转换。</p></blockquote><table tabindex="0"><thead><tr><th>设备</th><th style="text-align:center;">信号类型</th><th style="text-align:center;">是否需要 A/D</th></tr></thead><tbody><tr><td>麦克风</td><td style="text-align:center;">模拟（声波→模拟电信号）</td><td style="text-align:center;">✅ 需要</td></tr><tr><td>传感器</td><td style="text-align:center;">模拟（温度/压力等连续量）</td><td style="text-align:center;">✅ 需要</td></tr><tr><td>键盘</td><td style="text-align:center;">数字</td><td style="text-align:center;">❌</td></tr><tr><td>显示器</td><td style="text-align:center;">数字（接收数字信号）</td><td style="text-align:center;">❌（但需 D/A 从数字→模拟驱动）</td></tr><tr><td>打印机</td><td style="text-align:center;">数字</td><td style="text-align:center;">❌</td></tr></tbody></table><h3 id="⚠️-常见坑" tabindex="-1">⚠️ 常见坑 <a class="header-anchor" href="#⚠️-常见坑" aria-label="Permalink to &quot;⚠️ 常见坑&quot;">​</a></h3><table tabindex="0"><thead><tr><th>易错点</th><th>正解</th></tr></thead><tbody><tr><td>把 PCI 当串行总线</td><td>PCI 是<strong>并行</strong>总线，PCI Express (PCIe) 才是串行</td></tr><tr><td>RS-232 是网络接口</td><td>RS-232 是<strong>串行通信</strong>接口，不是网络接口（RJ45 才是）</td></tr><tr><td>麦克风是数字设备</td><td>麦克风输出<strong>模拟信号</strong>，必须经 A/D 转换</td></tr></tbody></table>',14)])])}const x=d(n,[["render",o]]);export{b as __pageData,x as default};
